css:
.memo-print {
font-family: "Helvetica Neue", Arial, sans-serif;
color: #1a1a1a;
font-size: 11pt;
line-height: 1.5;
}

.memo-header {
text-align: center;
border-bottom: 2px solid #1a1a1a;
padding-bottom: 12px;
margin-bottom: 20px;
}

.memo-brand {
font-size: 15pt;
font-weight: 700;
letter-spacing: 2px;
text-transform: uppercase;
}

.memo-subtitle {
font-size: 10pt;
letter-spacing: 1px;
text-transform: uppercase;
color: #555;
margin-top: 4px;
}

.memo-founder {
margin-bottom: 22px;
font-size: 10.5pt;
}

.memo-founder .founder-label {
font-weight: 700;
}

.memo-section {
margin-bottom: 16px;
}

.memo-section-title {
font-weight: 700;
font-size: 11.5pt;
text-transform: none;
border-bottom: 1px solid #ccc;
padding-bottom: 3px;
margin-bottom: 6px;
}

.memo-section-body {
white-space: pre-line;
}

.memo-links {
margin-bottom: 18px;
}

.memo-links div {
margin-bottom: 3px;
}

.memo-links .link-label {
font-weight: 700;
}

.memo-footer {
margin-top: 30px;
text-align: center;
font-size: 9pt;
letter-spacing: 1px;
text-transform: uppercase;
color: #777;
border-top: 1px solid #ccc;
padding-top: 8px;
}
